WITH filtered_store_sales AS (SELECT * FROM store_sales WHERE (revenue <= 1700 AND revenue >= 1300) OR revenue < 3500), summary AS (SELECT CASE WHEN revenue >= 3200 THEN 'high' WHEN revenue >= 900 THEN 'mid' ELSE 'low' END AS revenue_bucket, MAX(revenue) AS max_revenue, COUNT(*) AS num_store_sales FROM filtered_store_sales GROUP BY CASE WHEN revenue >= 3200 THEN 'high' WHEN revenue >= 900 THEN 'mid' ELSE 'low' END) SELECT revenue_bucket, max_revenue FROM summary ORDER BY max_revenue DESC
